import {ROPE_LAYOUT} from './rope-layout.js';
import * as THREE from 'three';import {autoFitOrthographicBounds} from '../camera-fit.js';import {SQUARE} from './layout.js';
export function createSquareView(parent,{slots=SQUARE.slots}={}){const root=new THREE.Group();root.name='square.floor-dots';parent.add(root);const geometry=new THREE.PlaneGeometry(.36,.36),material=new THREE.MeshBasicMaterial({color:'#d3c59c',transparent:true,opacity:.42,depthWrite:false});for(const slot of slots){const m=new THREE.Mesh(geometry,material);m.rotation.x=-Math.PI/2;m.position.set(slot.x,.047,slot.z);root.add(m);}let disposed=false;return{root,dispose(){if(disposed)return;disposed=true;root.removeFromParent();geometry.dispose();material.dispose();}};}
export function fitSquareCamera(camera,root,viewport,actors=[],{gathered=false,activity='exercise'}={}){root.updateWorldMatrix(true,true);camera.position.copy(root.localToWorld(activity==='rope'?new THREE.Vector3(1.8,9.8,14):new THREE.Vector3(7.5,8.5,13)));camera.up.set(0,1,0).transformDirection(root.matrixWorld);camera.lookAt(root.localToWorld(activity==='rope'?new THREE.Vector3(0,1.2,.8):new THREE.Vector3(0,1,1)));camera.updateMatrixWorld(true);const bounds=(gathered&&activity==='rope'?new THREE.Box3(new THREE.Vector3(...ROPE_LAYOUT.cameraBounds.min),new THREE.Vector3(...ROPE_LAYOUT.cameraBounds.max)):new THREE.Box3(new THREE.Vector3(gathered?-2.7:-5.05,.035,-1.4),new THREE.Vector3(gathered?2.7:5.05,2.05,gathered?2.7:5.55))).applyMatrix4(root.matrixWorld);for(const actor of actors){actor.root.updateWorldMatrix(true,true);actor.root.traverseVisible(n=>{if(!n.isMesh||!n.geometry?.attributes.position)return;n.geometry.computeBoundingBox();bounds.union(n.geometry.boundingBox.clone().applyMatrix4(n.matrixWorld));});}autoFitOrthographicBounds({camera,worldBounds:bounds,viewport,paddingPx:{top:20,right:18,bottom:20,left:18}});camera.updateMatrixWorld(true);return bounds;}
